concepts.code:
-- Silent bug: one NULL product_id empties the result
SELECT id FROM products
WHERE id NOT IN (SELECT product_id FROM recalls);

-- Correct: NULL rows never match, so they cannot block anything
SELECT p.id FROM products AS p
WHERE NOT EXISTS (SELECT 1 FROM recalls AS r WHERE r.product_id = p.id);

-- Also correct, if you must keep NOT IN
SELECT id FROM products
WHERE id NOT IN (SELECT product_id FROM recalls WHERE product_id IS NOT NULL);

-- Most urgent first, unset priority last, stable among equals
SELECT id, title, priority
FROM tickets
ORDER BY priority DESC NULLS LAST, id
LIMIT 5;

-- Standard spelling of LIMIT/OFFSET
SELECT id FROM tickets ORDER BY id OFFSET 10 ROWS FETCH FIRST 5 ROWS ONLY;

-- Return everyone tied with the 3rd row (Postgres 13+)
SELECT id, score FROM players ORDER BY score DESC FETCH FIRST 3 ROWS WITH TIES;

