exercises.schema:
CREATE TABLE products (
  id     int PRIMARY KEY,
  name   text NOT NULL,
  price  numeric(10,2) NOT NULL,
  active boolean NOT NULL
);
CREATE TABLE recalls (
  id         int PRIMARY KEY,
  product_id int,   -- NULL when the report did not name a product
  reason     text
);
